import{_ as t,o as a,c as s,ao as i}from"./chunks/framework.RK-kd4Sd.js";const k=JSON.parse('{"title":"Precompilation","description":"","frontmatter":{},"headers":[],"relativePath":"howto/precompile.md","filePath":"howto/precompile.md","lastUpdated":null}'),o={name:"howto/precompile.md"};function n(l,e,r,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="Precompilation" tabindex="-1">Precompilation <a class="header-anchor" href="#Precompilation" aria-label="Permalink to &quot;Precompilation {#Precompilation}&quot;">​</a></h1><p>The first plan for a new radix sequence compiles its kernels. Without preparation, that takes seconds for a size nobody has used before, which matters in short scripts, in a notebook that restarts, or in a service that starts and must answer quickly.</p><p>FFTL ships a precompile workload that runs common plans and transforms while the package is precompiled, so the compiled code is part of the package image. It is selected with a preference:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Preferences, FFTL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Preferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_preferences!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FFTL, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;precompile_workload&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;broad&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The next load recompiles FFTL with the new setting. The values are:</p><table tabindex="0"><thead><tr><th style="text-align:left;">value</th><th style="text-align:left;">content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;lean&quot;</code> (default)</td><td style="text-align:left;">lengths 1024, 1000 and 1009 in one dimension, 16 × 16 and 8 × 8 × 8, both element types, complex transforms, real transforms and <code>plan_pass</code></td></tr><tr><td style="text-align:left;"><code>&quot;broad&quot;</code></td><td style="text-align:left;">lengths 10⁵, 2²⁰, 128, 360, 243, the sizes 256 × 256 and 64 × 64 × 64, and a four-step case with four threads</td></tr><tr><td style="text-align:left;"><code>&quot;none&quot;</code></td><td style="text-align:left;">no workload: smallest image, compilation at the first use</td></tr></tbody></table><p>The workload applies plans and runs transforms, not just constructs them, because most of the compiled code is generated for the transform itself. A plan of a size the workload did not cover still compiles its own kernels when first used; the workload only moves that cost to package precompilation.</p><p><code>FFTL.PRECOMPILE_WORKLOAD</code> reports the value the package was built with.</p><p>The trade-off is size against latency. On an Apple M1 Max, the lean workload took about 32 s to precompile and makes the package image about 96 MB. The first plan and transform of a covered size then take milliseconds instead of seconds. Choose <code>&quot;none&quot;</code> when the image size matters more than the first call, for example in continuous integration.</p>`,9)])])}const m=t(o,[["render",n]]);export{k as __pageData,m as default};
